import {mapGetters} from "vuex";
import {selectOldDeviceSubmit} from "@/api/device/oldEquipmentLibrary.js";
export default {
  props: {
  },
  data() {
    return {
      isShow: true,
      searchForm: {
        current: 1,
        size: 20,
        deviceStatus:'',
        deviceType:'',
      },
      // 表格
      tableData: [
        {eprNum: 2023},
        {eprNum: 220},
      ],
      tableHeight: '550px',
      loading: false,
      total: 0,
      selectList: [],
      list: [],
      active:1,
      isEdit:false,
      btnTitle:'同步编辑',
    };
  },
  computed: {
    ...mapGetters(["userInfo", "userDetail"]),
    isVisible: {
      get() {
        return this.isVisible
      },
      set(val) {
        this.$emit("update:isShow", val)
      }
    }
  },
   mounted(){
    this.tableData = this.$route.query.data;
  },
  methods: {

    faultCountChange(value,row){
      if(this.isEdit){
        this.tableData.forEach(item => {
          if(value == 'e' || value == 'E'){
            item.faultCount = '';
          }else{
             item.faultCount =  value.replace(/[^\d]/g,'')
          }

        });
      }else{
         if(value == 'e' || value == 'E'){
            row.faultCount = '';
          }else{
             row.faultCount =  value.replace(/[^\d]/g,'')
          }
      }
    },
    faultDetailChange(value,row){
      if(this.isEdit){
        this.tableData.forEach(item => {
          item.faultDetail = value;
        });
      }else{
         row.faultDetail = value;
      }
    },
    hiddenCountChange(value,row){
      if(this.isEdit){
        this.tableData.forEach(item => {
           if(value == 'e' || value == 'E'){
            item.hiddenCount = '';
          }else{
             item.hiddenCount =  value.replace(/[^\d]/g,'')
          }
        });
      }else{
         if(value == 'e' || value == 'E'){
            row.hiddenCount = '';
          }else{
             row.hiddenCount =  value.replace(/[^\d]/g,'')
          }
      }

    },
    hiddenDetailChange(value,row){
       if(this.isEdit){
        this.tableData.forEach(item => {
          item.hiddenDetail = value;
        });
      }else{
         row.hiddenDetail = value;
      }
      this.$forceUpdate();
    },
     select(val) {
      this.selectList = val;
    },

    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      this.tableHeight = pageBody[0].offsetHeight - 50 - 47 + 'px'
    },

     handleSubmit() {
      let paramsList = [];
      if (this.selectList.length == 0) {
         if(this.tableData.length > 0){
           paramsList = [...this.tableData];
         }
         else{
          paramsList = [];
          this.$message.warning("当前暂无设备!")
          return
         }


      }else{
          paramsList = [...this.selectList];
      }

    let canSave = true;
    if(paramsList.length > 0){
          paramsList.map((item,index)=> {
         if(!item.faultCount){
           this.$message.warning('存在必填项为空，请填写完整再保存！')
           canSave = false;
           return
         }
          if(!item.faultDetail){
         this.$message.warning('存在必填项为空，请填写完整再保存！')
           canSave = false;
           return
         }

          if(!item.hiddenCount){
          this.$message.warning('存在必填项为空，请填写完整再保存！')
           canSave = false;
           return
         }

          if(!item.hiddenDetail){
           this.$message.warning('存在必填项为空，请填写完整再保存！')
           canSave = false;
           return
         }
      })
   }

   if(canSave){
        selectOldDeviceSubmit(paramsList).then((res) => {
        if (res.code != 200) {
          throw res.msg;
        }
        this.active = 2;
        this.$message({
          message: "提交设备成功",
          type: "success",
        });
           this.$closePage("");

         setTimeout(() => {
           this.$EventBus.$emit('onClosePage');
         }, 100);

       });
   }





    },
    // 编辑
    handleEdit() {
       if(this.isEdit == false){
         this.$confirm('此操作将会同步所有设备数据的当前编辑选项，是否继续?','提示',{
          confirmButtonText:'确定',
          cancelButtonText:'取消',
          type:'warning',
         }).then(()=>{
          this.isEdit = true;
          this.btnTitle = '取消同步编辑'

         }).catch(()=>{
          this.isEdit = false;
          this.btnTitle = '同步编辑'
         })
       }else{
         this.$message.warning('取消同步编辑');
         this.btnTitle = '同步编辑'
         this.isEdit = false;
       }
    },
    // 移除
    handleDelete() {
      this.tableData = this.tableData.filter(aItem => !this.selectList.some(bItem => bItem.deviceCode === aItem.deviceCode));
    },

    handleCancel(){
        this.$router.back();
    },
  }
};
